import requests

class WeatherAPI:
    def __init__(self, api_key):
        self.api_key = api_key

    def get_weather_data(self, city: str, date: str) -> dict:
        url = f"https://api.weatherprovider.com/weather?city={city}&date={date}&api_key={self.api_key}"
        response = requests.get(url)
        if response.status_code == 200:
            return response.json()
        else:
            return {}

    def post_user_preferences(self, url: str, preferences: dict, email: str) -> bool:
        headers = {'Content-Type': 'application/json'}
        data = {
            'preferences': preferences,
            'email': email
        }
        response = requests.post(url, json=data, headers=headers)
        if response.status_code == 200:
            return True
        else:
            return False

    def put_user_preferences(self, url: str, preferences: dict, email: str) -> bool:
        headers = {'Content-Type': 'application/json'}
        data = {
            'preferences': preferences,
            'email': email
        }
        response = requests.put(url, json=data, headers=headers)
        if response.status_code == 200:
            return True
        else:
            return False

    def delete_user_preferences(self, url: str, email: str) -> bool:
        headers = {'Content-Type': 'application/json'}
        data = {
            'email': email
        }
        response = requests.delete(url, json=data, headers=headers)
        if response.status_code == 200:
            return True
        else:
