```javascript
// Function to make the AJAX request
function makeRequest(url, onSuccess, onError) {
  var xhr = new XMLHttpRequest();
  xhr.open('GET', url);
  xhr.onload = function() {
    if (xhr.status === 200) {
      onSuccess(xhr.response);
    } else {
      onError(xhr.status);
    }
  };
  xhr.onerror = function() {
    onError(xhr.status);
  };
  xhr.send();
}

// Function to parse and display specific data in a modal pop-up
function displayData(response) {
  var data = JSON.parse(response);

  // Extract the specific data you want to display
  var specificData = data.specificProperty;

  // Create a modal pop-up window
  var modal = document.createElement('div');
  modal.classList.add('modal');

  // Add the specific data to the modal
  var content = document.createElement('p');
  content.textContent = specificData;
  modal.appendChild(content);

  // Add the modal to the document
  document.body.appendChild(modal);
}

// Function to handle any errors that occur during the AJAX request
function handleError(error) {
  console.error('Error:', error);
}

// URL of the API endpoint
var apiUrl = 'https://api.example.com/data';

// Make the AJAX request and handle the response
makeRequest(apiUrl, displayData, handleError);
```

