        }
        $('#number').html(selectOptions);
      }
    });

    // Function to calculate factorial and display it
    function calculateFactorial() {
      var selectedNumber = parseInt($('#number').val());
      var factorial = 1;
      for (var i = 2; i <= selectedNumber; i++) {
        factorial *= i;
      }
      $('#result').text('Factorial of ' + selectedNumber + ' is: ' + factorial);
    }

    // Event listener for form submission
    $('#factorialForm').submit(function(event) {
      event.preventDefault();
      calculateFactorial();
    });
  </script>
