// Weather API endpoint
const API_URL = 'https://api.openweathermap.org/data/2.5/weather';
const API_KEY = 'YOUR_API_KEY';

// Cache to store weather data
const weatherCache = {};

// Function to fetch weather data for a city
async function fetchWeather(city) {
  // Check if weather data is already in cache and is not older than an hour
  if (weatherCache[city] && Date.now() - weatherCache[city].timestamp < 3600000) {
    return weatherCache[city].data;
  }

  try {
    // Make API call to fetch weather data
    const response = await fetch(`${API_URL}?q=${city}&appid=${API_KEY}`);
    const data = await response.json();

    // Check if city is found in the API response
    if (data.cod === '404') {
      throw new Error('City not found');
    }

    // Store weather data in cache
    weatherCache[city] = {
      data: data,
      timestamp: Date.now()
    };

    return data;
  } catch (error) {
    throw new Error('Failed to fetch weather data');
  }
}

