Create a Node.js server to handle POST, GET, PUT, and DELETE requests and store the incoming data in a PostgreSQL database. The server should implement authentication using JWT and only allow authorized users to access, modify, or delete the stored data. The server should also have a rate limiting mechanism that restricts the number of requests a user can make within a certain time period, with different rate limits for different API endpoints. The server should also implement input validation and sanitize all user inputs to prevent SQL injection attacks.

### Response:
Sure! Here's an example of a Node.js server that handles POST, GET, PUT, and DELETE requests, stores the incoming data in a PostgreSQL database, implements JWT authentication, rate limiting, input validation, and sanitization.

First, make sure you have PostgreSQL and its Node.js driver (pg) installed.

Install dependencies:
```
npm install express pg jsonwebtoken express-rate-limit express-validator
```

Now, let's create a server file (server.js):

```javascript
const express = require('express');
const { Pool } = require('pg');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

// PostgreSQL configuration
const pool = new Pool({
  user: 'your-username',
  host: 'localhost',
  database: 'your-database',
  password: 'your-password',
  port: 5432,
});

// Express server configuration
const app = express();
const port = 3000;

// JWT secret key
const secretKey = 'your-secret-key';

// Rate limiter configuration
const apiLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100, // limit each IP to 100 requests per windowMs
});

// Middleware to parse JSON body
app.use(express.json());

// API endpoints
app.post('/api/data', apiLimiter, authenticateToken, validateData, (req, res) => {
  const { data } = req.body;
  const userId = req.user.id;

  pool.query('INSERT INTO data (user_id, data) VALUES ($1, $2)', [userId, data], (error) => {
    if (error) {
      console.error('Error storing data:', error);
      res.status(500).json({ error: 'Internal server error' });
    } else {
      res.sendStatus(201);
    }
  });
});

app.get('/api/data', apiLimiter, authenticateToken, (req, res) => {
  const userId = req.user.id;

  pool.query('SELECT * FROM data WHERE user_id = $1', [userId], (error, result) => {
    if (error) {
      console.error('Error retrieving data:', error);
      res.status(500).json({ error: 'Internal server error' });
    } else {
      res.json(result.rows);
    }
  });
});

app.put('/api/data/:id', apiLimiter, authenticateToken, validateData, (req, res) => {
  const { id } = req.params;
  const { data } = req.body;
  const userId = req.user.id;

  pool.query(
    'UPDATE data SET data = $1 WHERE id = $2 AND user_id = $3',
    [data, id, userId],
    (error, result) => {
      if (error) {
        console.error('Error updating data:', error);
        res.status(500).json({ error: 'Internal server error' });
      } else if (result.rowCount === 0) {
        res.status(404).json({ error: 'Data not found' });
      } else {
        res.sendStatus(204);
      }
    }
  );
});

app.delete('/api/data/:id', apiLimiter, authenticateToken, (req, res) => {
  const { id } = req.params;
  const userId = req.user.id;

  pool.query(
    'DELETE FROM data WHERE id = $1 AND user_id = $2',
    [id, userId],
    (error, result) => {
      if (error) {
        console.error('Error deleting data:', error);
        res.status(500).json({ error: 'Internal server error' });
      } else if (result.rowCount === 0) {
        res.status(404).json({ error: 'Data not found' });
      } else {
        res.sendStatus(204);
      }
    }
  );
});

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.sendStatus(401);
  }

  jwt.verify(token, secretKey, (error, user) => {
    if (error) {
      console.error('Error verifying JWT:', error);
      return res.sendStatus(403);
    }

    req.user = user;
    next();
  });
}

// Data validation middleware
function validateData(req, res, next) {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  next();
}

// Start the server
app.listen(port, () => {
  console.log(`Server is listening on port ${port}`);
});
```

In the above code, replace `'your-username'`, `'your-database'`, and `'your-password'` with your PostgreSQL credentials. Also, replace `'your-secret-key'` with your desired secret key for JWT.

To run the server, execute the following command:
```
node server.js
```

