```javascript
const express = require('express');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const { Sequelize, DataTypes } = require('sequelize');

const app = express();
app.use(express.json());

const sequelize = new Sequelize('database', 'username', 'password', {
  dialect: 'sqlite',
  storage: 'database.sqlite'
});

const User = sequelize.define('User', {
  id: {
    type: DataTypes.UUID,
    defaultValue: DataTypes.UUIDV4,
    primaryKey: true
  },
  username: {
    type: DataTypes.STRING,
    allowNull: false,
    unique: true
  },
  password: {
    type: DataTypes.STRING,
    allowNull: false
  }
});

// Sync the database models
(async () => {
  await sequelize.sync();
})();

// Middleware for authentication
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (token == null) return res.sendStatus(401);

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
};

// Middleware for error handling
const handleErrors = (err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
};

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

// Root route
app.get('/', (req, res) => {
  res.sendFile(__dirname + '/index.html');
});

// User registration route
app.post('/register', [
  body('username').isLength({ min: 3 }),
  body('password').isLength({ min: 6 })
], async (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { username, password } = req.body;
  try {
    const salt = await bcrypt.genSalt(10);
    const hashedPassword = await bcrypt.hash(password, salt);
    await User.create({ username, password: hashedPassword });
    res.sendStatus(201);
  } catch (err) {
    next(err);
  }
});

// User login route
app.post('/login', limiter, async (req, res, next) => {
  const { username, password } = req.body;
  try {
    const user = await User.findOne({ where: { username } });
    if (!user) {
      return res.status(400).json({ error: 'Invalid username or password' });
    }

    const passwordMatch = await bcrypt.compare(password, user.password);
    if (!passwordMatch) {
      return res.status(400).json({ error: 'Invalid username or password' });
    }

    const accessToken = jwt.sign({ username: user.username }, process.env.ACCESS_TOKEN_SECRET);
    res.json({ accessToken });
  } catch (err) {
    next(err);
  }
});

// User list API endpoint with pagination and search functionality
app.get('/users', authenticateToken, async (req, res, next) => {
  const { page = 1, limit = 10, search = '' } = req.query;
  try {
    const users = await User.findAll({
      where: { username: { [Sequelize.Op.like]: `%${search}%` } },
      limit: +limit,
      offset: (+page - 1) * +limit
    });
    res.json(users);
  } catch (err) {
    next(err);
  }
});

// User details API endpoint
app.get('/users/:id', authenticateToken, async (req, res, next) => {
  const { id } = req.params;
  try {
    const user = await User.findByPk(id);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  } catch (err) {
    next(err);
  }
});

app.use(handleErrors);

// Start the server
app.listen(3000, () => {
  console.log('Server started on port 3000');
});
```

Make sure to install the required dependencies by running `npm install express bcrypt jsonwebtoken express-rate-limit sequelize sqlite3` in the terminal. Also, create an `index.html` file in the same directory as the server file to serve as the web page for the root route.

