```swift
import Foundation

let clientId = "YOUR_CLIENT_ID"
let clientSecret = "YOUR_CLIENT_SECRET"
let apiUrl = "YOUR_API_URL"

// Create a struct to hold the access token
struct AccessToken: Codable {
    let token: String
}

// Create a function to handle OAuth 2.0 authentication and get the access token
func getAccessToken(completion: @escaping (Result<AccessToken, Error>) -> Void) {
    // Create the request URL
    let authUrl = "https://api.example.com/oauth/token"
    let body = "grant_type=client_credentials&client_id=\(clientId)&client_secret=\(clientSecret)"
    let data = body.data(using: .utf8)

    var request = URLRequest(url: URL(string: authUrl)!)
    request.httpMethod = "POST"
    request.httpBody = data

    // Send the request
    URLSession.shared.dataTask(with: request) { (data, response, error) in
        if let error = error {
            completion(.failure(error))
            return
        }

        guard let data = data else {
            completion(.failure(NSError(domain: "", code: 0, userInfo: nil)))
            return
        }

        // Parse the JSON response
        do {
            let accessToken = try JSONDecoder().decode(AccessToken.self, from: data)
            completion(.success(accessToken))
        } catch {
            completion(.failure(error))
        }
    }.resume()
}

// Create a function to make the API request using the access token
func makeAPIRequest(accessToken: String, completion: @escaping (Result<String, Error>) -> Void) {
    // Create the request URL
    let apiUrlWithParams = "\(apiUrl)?access_token=\(accessToken)"
    let request = URLRequest(url: URL(string: apiUrlWithParams)!)

    // Send the request
    URLSession.shared.dataTask(with: request) { (data, response, error) in
        if let error = error {
            completion(.failure(error))
            return
        }

        guard let data = data else {
            completion(.failure(NSError(domain: "", code: 0, userInfo: nil)))
            return
        }

        // Parse the response
        if let responseString = String(data: data, encoding: .utf8) {
            completion(.success(responseString))
        } else {
            completion(.failure(NSError(domain: "", code: 0, userInfo: nil)))
        }
    }.resume()
}

// Make the API request
getAccessToken { result in
    switch result {
    case .success(let accessToken):
        makeAPIRequest(accessToken: accessToken.token) { result in
            switch result {
            case .success(let response):
                print("API Response: \(response)")
            case .failure(let error):
                print("API Error: \(error)")
            }
        }
    case .failure(let error):
        print("Authentication Error: \(error)")
    }
}
```

