```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const multer = require('multer');
const app = express();
const PORT = 3000;

// Middleware to parse JSON requests
app.use(express.json());

// Authentication middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization;

  if (!token) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  try {
    const decoded = jwt.verify(token, 'secret-key');
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(401).json({ message: 'Invalid token' });
  }
};

// Authorization middleware
const authorize = (roles) => {
  return (req, res, next) => {
    if (!roles.includes(req.user.role)) {
      return res.status(403).json({ message: 'Forbidden' });
    }
    next();
  };
};

// Product data
let products = [];

// Multer storage configuration for file uploads
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, 'uploads/');
  },
  filename: (req, file, cb) => {
    cb(null, Date.now() + '-' + file.originalname);
  },
});

// File filter for image uploads
const fileFilter = (req, file, cb) => {
  if (file.mimetype === 'image/jpeg' || file.mimetype === 'image/png') {
    cb(null, true);
  } else {
    cb(null, false);
  }
};

const upload = multer({
  storage,
  limits: {
    fileSize: 1024 * 1024 * 5, // 5MB limit
  },
  fileFilter,
});

// Routes
app.get('/products', authenticate, (req, res) => {
  // Pagination options
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;
  const startIndex = (page - 1) * limit;
  const endIndex = page * limit;
  const results = {};

  // Filter and sort options
  const minPrice = parseInt(req.query.minPrice) || 0;
  const maxPrice = parseInt(req.query.maxPrice) || Number.MAX_SAFE_INTEGER;
  const category = req.query.category || '';
  const sortBy = req.query.sortBy || 'name';

  // Filter products
  const filteredProducts = products
    .filter(
      (product) =>
        product.price >= minPrice &&
        product.price <= maxPrice &&
        product.category.toLowerCase().includes(category.toLowerCase())
    )
    .sort((a, b) => {
      if (sortBy === 'price') {
        return a.price - b.price;
      } else {
        return a.name.localeCompare(b.name);
      }
    });

  // Pagination results
  results.totalCount = filteredProducts.length;
  if (endIndex < filteredProducts.length) {
    results.next = {
      page: page + 1,
      limit,
    };
  }
  if (startIndex > 0) {
    results.previous = {
      page: page - 1,
      limit,
    };
  }
  results.products = filteredProducts.slice(startIndex, endIndex);

  res.json(results);
});

app.post('/products', authenticate, authorize(['admin']), upload.single('image'), (req, res) => {
  const { name, price, category } = req.body;

  // Validate image upload
  if (!req.file) {
    return res.status(400).json({ message: 'No image uploaded' });
  }

  // Create new product
  const product = {
    id: products.length + 1,
    name,
    price,
    category,
    image: req.file.path,
  };
  products.push(product);

  res.status(201).json({ message: 'Product created', product });
});

app.put('/products/:id', authenticate, authorize(['admin']), (req, res) => {
  const { id } = req.params;
  const { name, price, category } = req.body;

  // Find product by ID
  const product = products.find((product) => product.id === parseInt(id));

  if (!product) {
    return res.status(404).json({ message: 'Product not found' });
  }

  // Update product information
  product.name = name || product.name;
  product.price = price || product.price;
  product.category = category || product.category;

  res.json({ message: 'Product updated', product });
});

app.delete('/products/:id', authenticate, authorize(['admin']), (req, res) => {
  const { id } = req.params;

  // Find product by ID
  const index = products.findIndex((product) => product.id === parseInt(id));

  if (index === -1) {
    return res.status(404).json({ message: 'Product not found' });
  }

  // Delete product
  products.splice(index, 1);

  res.json({ message: 'Product deleted' });
});

// Start server
app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
```

