import React, { useState, useEffect } from 'react';

const UserList = () => {
  const [users, setUsers] = useState([]);

  useEffect(() => {
    fetch('https://example.com/users')
      .then(response => response.json())
      .then(data => {
        const sortedUsers = data.sort((a, b) => a.name.localeCompare(b.name)).reverse();
