import requests

class WeatherAPIHandler:
    def get_weather_data(self, city: str) -> dict:
        url = f"https://api.weatherprovider.com/weather?city={city}"
        response = requests.get(url)
        if response.status_code == 200:
            return response.json()
        else:
            return {}

    def post_user_preferences(self, url: str, preferences: dict) -> bool:
        response = requests.post(url, json=preferences)
        if response.status_code == 201:
