```javascript
const apiUrl = 'https://api.example.com/endpoint';

async function postData(url, data) {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(data),
    });

    if (!response.ok) {
      throw new Error(`Server responded with ${response.status}`);
    }

    const result = await response.json();
    return result;
  } catch (error) {
    throw new Error(`Error: ${error.message}`);
  }
}

function retryWithDelay(url, data, maxRetries, delay) {
  return new Promise(async (resolve, reject) => {
    let retries = 0;
    while (retries < maxRetries) {
      try {
        const result = await postData(url, data);
        resolve(result);
        return;
      } catch (error) {
        retries++;
        console.log(error.message);
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
    reject(new Error('Max retries exceeded'));
  });
}

function makeApiCall(url, data) {
  return new Promise(async (resolve, reject) => {
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => {
        controller.abort();
        reject(new Error('Request timed out'));
      }, 5000);

      const result = await retryWithDelay(url, data, 3, 1000, controller);

      clearTimeout(timeout);
      resolve(result);
    } catch (error) {
      reject(error);
    }
  });
}

// Usage:
const payload = {
  username: 'john',
  password: 'secret',
};

makeApiCall(apiUrl, payload)
  .then((response) => console.log(response))
  .catch((error) => console.error(error));
```

