```javascript
const http = require('http');
const url = require('url');
const querystring = require('querystring');

const server = http.createServer((req, res) => {
  const { pathname, query } = url.parse(req.url);
  const params = querystring.parse(query);

  if (pathname === '/') {
    if (req.method === 'GET') {
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.write(`
        <html>
        <head>
          <title>Greetings Page</title>
        </head>
        <body>
          <h1>Welcome to the Greetings Page</h1>
          <form action="/greet" method="POST">
            <label for="name">Enter your name:</label>
            <input type="text" name="name" id="name">
            <button type="submit">Submit</button>
          </form>
        </body>
        </html>
      `);
      res.end();
    } else if (req.method === 'POST') {
      const { name } = params;
      if (name && name.length >= 3 && /^[a-zA-Z]+$/.test(name)) {
        const randomNum = Math.floor(Math.random() * 100) + 1;

        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.write(`
          <html>
          <head>
            <title>Greetings Page</title>
          </head>
          <body>
            <h1>Hello, ${name}!</h1>
            <p>Your random number is: ${randomNum}</p>
          </body>
          </html>
        `);
        res.end();
      } else {
        res.writeHead(400, { 'Content-Type': 'text/html' });
        res.write(`
          <html>
          <head>
            <title>Greetings Page - Error</title>
          </head>
          <body>
            <h1>Error</h1>
            <p>Invalid name. Please enter a valid name (at least 3 characters long, only alphabets).</p>
            <a href="/">Go back</a>
          </body>
          </html>
        `);
        res.end();
      }
    }
  } else {
    res.writeHead(404, { 'Content-Type': 'text/html' });
    res.write(`
      <html>
      <head>
        <title>Not Found</title>
      </head>
      <body>
        <h1>404 - Not Found</h1>
      </body>
      </html>
    `);
    res.end();
  }
});

server.listen(8080, () => {
  console.log('Server listening on port 8080');
});
```

In this example, we create an HTTP server using the `http` module. The server listens on port 8080. When a GET request is made to the root path (`/`), the server responds with a form asking the user to enter their name. When a POST request is made to the `/greet` path with a valid name, the server generates a random number between 1 and 100 and displays a personalized greeting with the random number. If an invalid name is entered or the request is not a POST request, appropriate error messages are displayed.

To run this server, save the code in a file (e.g., `server.js`) and run it using NodeJS:

```
