const express = require('express');
const bcrypt = require('bcrypt');
const app = express();
const PORT = 3000;

// Assume we have a database object with methods for querying and saving data
const database = {
  users: []
};

// Middleware to parse JSON request body
app.use(express.json());

// API endpoint for user registration
app.post('/register', (req, res) => {
  const { firstName, lastName, email, password, confirmPassword } = req.body;

  // Check if all fields are provided
  if (!firstName || !lastName || !email || !password || !confirmPassword) {
    return res.status(400).json({ error: 'All fields are required' });
  }

  // Check if the email already exists
  if (database.users.find(user => user.email === email)) {
    return res.status(400).json({ error: 'Email already exists' });
  }

  // Check if the email is valid
  const emailRegex = /^\S+@\S+\.\S+$/;
  if (!emailRegex.test(email)) {
    return res.status(400).json({ error: 'Invalid email address' });
  }

  // Check if the password is at least 8 characters long and contains the required characters
  const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;
  if (!passwordRegex.test(password)) {
    return res.status(400).json({
      error:
        'Password must be at least 8 characters long and contain a combination of uppercase letters, lowercase letters, numbers, and special characters'
    });
  }

  // Check if the password and confirm password match
  if (password !== confirmPassword) {
    return res.status(400).json({ error: 'Password and confirm password do not match' });
  }

  // Hash the password
  const hashedPassword = bcrypt.hashSync(password, 10);

  // Save the user's information in the database
  const user = {
    firstName,
    lastName,
    email,
    password: hashedPassword
  };
  database.users.push(user);

  return res.status(201).json({ message: 'Registration successful' });
});

