Replace `your-username`, `your-password`, `your-database`, and `your-table` with your MySQL database credentials and table name.

3. In the same directory, create a new HTML file called `index.html` and add the following code:

```html
<!DOCTYPE html>
<html>
<head>
  <title>Infinite Scroll Example</title>
  <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
  <script>
    $(document).ready(function() {
      var offset = 0;
      var limit = 10;

      function fetchData() {
        $.ajax({
          url: '/api/data',
          method: 'GET',
          data: { offset: offset },
          success: function(response) {
            if (response.length === 0) {
              $(window).off('scroll');
            }

            response.forEach(function(row) {
              var $tr = $('<tr>').append(
                $('<td>').text(row.column1),
                $('<td>').text(row.column2),
                // Add more columns as needed
              );

              $('#data-table').append($tr);
            });

            offset += limit;
          },
          error: function(jqXHR, textStatus, errorThrown) {
            console.log('Error:', textStatus, errorThrown);
          }
        });
      }

      fetchData();

      $(window).scroll(function() {
        if ($(window).scrollTop() + $(window).height() >= $(document).height()) {
          fetchData();
        }
      });
    });
  </script>
</head>
