import React, { useState, useEffect } from 'react';

const SubmitButton = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [isError, setIsError] = useState(false);
  const [isCanceled, setIsCanceled] = useState(false);
  const [progress, setProgress] = useState(0);
  const [response, setResponse] = useState(null);
  const [cachedResponse, setCachedResponse] = useState(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      setIsError(true);
      setIsLoading(false);
    }, 10000);

    return () => clearTimeout(timer);
  }, []);

  const handleClick = () => {
    setIsLoading(true);
    setIsError(false);
    setIsCanceled(false);
    setProgress(0);

    if (cachedResponse) {
      setResponse(cachedResponse);
      setIsLoading(false);
      return;
    }

    fetch('https://api.example.com/endpoint')
      .then(response => {
        setProgress(100);
        return response.json();
      })
      .then(data => {
        setResponse(data);
        setCachedResponse(data);
        setIsLoading(false);
      })
      .catch(error => {
        setIsError(true);
        setIsLoading(false);
      });
  };

  const handleCancel = () => {
    setIsCanceled(true);
    setIsLoading(false);
    setProgress(0);
    setResponse(null);
  };

  return (
    <div>
      <button onClick={handleClick} disabled={isLoading || isCanceled}>
        {isLoading ? 'Loading...' : 'Submit'}
      </button>
      {isLoading && <progress value={progress} max="100" />}
      {isCanceled && <p>API call was canceled successfully.</p>}
      {isError && <p>Error occurred during API call.</p>}
      {response && !isLoading && (
        <div>
          <p>API call succeeded!</p>
          <pre>{JSON.stringify(response, null, 2)}</pre>
        </div>
      )}
    </div>
  );
};

export default SubmitButton;
