```javascript
const express = require('express');
const bodyParser = require('body-parser');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(bodyParser.json());

// Predefined list of valid API keys
const validAPIKeys = ['your-api-key-1', 'your-api-key-2'];

// Persistent storage system (MongoDB in this example)
const mongoose = require('mongoose');
mongoose.connect('mongodb://localhost:27017/users', {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// User schema and model
const userSchema = new mongoose.Schema({
  _id: String,
  name: String,
  email: String,
  password: String,
});
const User = mongoose.model('User', userSchema);

// Middleware to enforce API key authentication
const authenticateAPIKey = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];

  if (validAPIKeys.includes(apiKey)) {
    next();
  } else {
    res.status(401).json({ error: 'Unauthorized' });
  }
};

// Create a new user
app.post('/users', authenticateAPIKey, (req, res) => {
  const { name, email, password } = req.body;

  // Validate request body
  if (!name || typeof name !== 'string' ||
      !email || typeof email !== 'string' ||
      !password || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid request body' });
  }

  // Generate unique identifier for the user
  const userId = uuidv4();

  // Create a new user in the database
  const newUser = new User({
    _id: userId,
    name: name,
    email: email,
    password: password,
  });
  newUser.save()
    .then(() => {
      res.status(201).json({ id: userId });
    })
    .catch((error) => {
      res.status(500).json({ error: 'Internal server error' });
    });
});

// Retrieve a user by ID
app.get('/users/:id', authenticateAPIKey, (req, res) => {
  const userId = req.params.id;

  // Find the user in the database
  User.findById(userId, 'name email')
    .then((user) => {
      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      res.status(200).json(user);
    })
    .catch((error) => {
      res.status(500).json({ error: 'Internal server error' });
    });
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

To run this code, make sure you have Node.js and MongoDB installed. You also need to install the required dependencies by running `npm install express body-parser mongoose uuid` in the project directory. Then, you can start the server by running `node app.js`.

