          const bValue = b.children[column].textContent.toLowerCase();
          return aValue.localeCompare(bValue);
        });

        if (th.classList.contains('asc')) {
          th.classList.remove('asc');
          th.classList.add('desc');
          rows.reverse();
        } else {
          th.classList.remove('desc');
