const getProducts = async () => {
  // Make API call to getProducts endpoint
  const response = await fetch('https://example.com/getProducts');
  const data = await response.json();

  // Store the products in a variable
  const products = data.products;

  // Calculate total price of all products
  let totalPrice = 0;
  for (const product of products) {
    totalPrice += product.price * product.quantity;
  }
  totalPrice = totalPrice.toFixed(2);

  // Calculate average price of all products
  const averagePrice = (totalPrice / products.length).toFixed(2);

  // Find product with highest price and lowest quantity
  let highestPriceProduct = products[0];
  for (const product of products) {
    if (product.price > highestPriceProduct.price) {
      highestPriceProduct = product;
    } else if (product.price === highestPriceProduct.price && product.quantity < highestPriceProduct.quantity) {
      highestPriceProduct = product;
    }
  }

  // Sort products by price in descending order
  products.sort((a, b) => {
    if (a.price === b.price) {
      return a.quantity - b.quantity;
    }
    return b.price - a.price;
  });

  // Create new array containing products with quantity less than 5
  const lowStockProducts = products.filter(product => product.quantity < 5);

  // Create new array containing products with price greater than or equal to 200
  const highPriceProducts = products.filter(product => product.price >= 200);

  // Create new object storing product quantities
