  for (const product of products) {
    if (product.quantity > 0) {
      productQuantities[product.id] = product.quantity;
    }
  }

  return {
    products,
    totalPrice,
    averagePrice,
    highestPriceProduct,
    lowStockProducts,
    highPriceProducts,
    productQuantities
  };
};

