  if (weatherCache[city] && Date.now() - weatherCache[city].timestamp < 3600000) {
    return weatherCache[city].data;
  }

  try {
    // Make API call to fetch weather data
    const response = await fetch(`${API_URL}?q=${city}&appid=${API_KEY}`);
    const data = await response.json();

    // Check if city is found in the API response
    if (data.cod === '404') {
      throw new Error('City not found');
    }

    // Store weather data in cache
    weatherCache[city] = {
      data: data,
      timestamp: Date.now()
    };

    return data;
  } catch (error) {
    throw new Error('Failed to fetch weather data');
  }
}

// Function to convert temperature from Kelvin to Celsius
function kelvinToCelsius(kelvin) {
  return kelvin - 273.15;
}

// Function to convert temperature from Kelvin to Fahrenheit
function kelvinToFahrenheit(kelvin) {
  return (kelvin - 273.15) * (9/5) + 32;
}

// Function to display weather data in table format
function displayWeatherData(weatherData) {
  // Clear existing table
  const table = document.querySelector('table');
  table.innerHTML = '';

  // Create table headers
