```javascript
const axios = require('axios');
const { MongoClient } = require('mongodb');

// API endpoint URL
const apiUrl = 'https://api.example.com/users';

// MongoDB connection string
const mongoUrl = 'mongodb://localhost:27017';

// MongoDB database and collection names
const dbName = 'userDb';
const collectionName = 'users';

// Function to retrieve all users from the API endpoint
async function retrieveUsersFromApi() {
  try {
    // Make a GET request to the API endpoint
    const response = await axios.get(apiUrl);
    const users = response.data;

    // Extract relevant information from each user object
    const extractedUsers = users.map(user => {
      return {
        id: user.id,
        name: user.name,
        email: user.email
      };
    });

    // Store the extracted information in the database
    await storeUsersInDatabase(extractedUsers);

    // Pagination: check if there are more pages of users
    if (response.headers['next-page']) {
      // Call the function recursively to retrieve the next page of users
      await retrieveUsersFromApi(response.headers['next-page']);
    }
  } catch (error) {
    console.error('Error retrieving users:', error);
  }
}

// Function to store the extracted users in the database
async function storeUsersInDatabase(users) {
  try {
    // Connect to the MongoDB server
    const client = await MongoClient.connect(mongoUrl);
    const db = client.db(dbName);

    // Insert the users into the database collection
    const collection = db.collection(collectionName);
    await collection.insertMany(users);

    // Close the MongoDB connection
    client.close();
  } catch (error) {
    console.error('Error storing users in database:', error);
  }
}

// Run the function to retrieve users from the API and store them in the database
retrieveUsersFromApi();
