    retryCount++;
    setTimeout(makeAjaxCall, 2000); // Retry after 2 seconds
  } else {
    displayError("Maximum retry limit reached");
  }
}

function displayResponse(response) {
  // Handle the response data and display it on the webpage
  console.log(response);
}

function displayError(error) {
  // Handle the error and display it on the webpage
  console.error(error);
}

makeAjaxCall();
```

