```javascript
const API_URL = "https://api.example.com/users";
const PAGE_SIZE = 10;

let users = [];
let currentPage = 1;

function fetchData() {
  fetch(API_URL)
    .then(response => response.json())
    .then(data => {
      users = data;
      renderTable();
    })
    .catch(error => {
      displayError("Error fetching data from API: " + error.message);
    });
}

function renderTable() {
  const tableBody = document.getElementById("table-body");
  tableBody.innerHTML = "";

  const startIndex = (currentPage - 1) * PAGE_SIZE;
  const endIndex = currentPage * PAGE_SIZE;

  const filteredUsers = applyFilters(users);
  const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

  paginatedUsers.forEach(user => {
    const row = document.createElement("tr");
    row.innerHTML = `
      <td>${user.name}</td>
      <td>${user.age}</td>
      <td>${user.gender}</td>
      <td>${user.location}</td>
    `;
    tableBody.appendChild(row);
  });

  updatePagination();
}

function applyFilters(users) {
  const searchKeyword = document.getElementById("search").value.trim().toLowerCase();
  const filterOption = document.getElementById("filter").value;

  return users.filter(user => {
    const matchesSearch = user.name.toLowerCase().includes(searchKeyword);
    const matchesFilter = filterOption === "" || user.gender === filterOption;
    return matchesSearch && matchesFilter;
  });
}

function sortTable(column) {
  users.sort((a, b) => {
    if (a[column] < b[column]) return -1;
    if (a[column] > b[column]) return 1;
    return 0;
  });
  renderTable();
}

function filterTable() {
  currentPage = 1;
  renderTable();
}

function updatePagination() {
  const pageElement = document.getElementById("page-number");
  pageElement.textContent = "Page " + currentPage;
}

function previousPage() {
  if (currentPage > 1) {
    currentPage--;
    renderTable();
  }
}

function nextPage() {
  const filteredUsers = applyFilters(users);
  const maxPage = Math.ceil(filteredUsers.length / PAGE_SIZE);
  if (currentPage < maxPage) {
    currentPage++;
    renderTable();
  }
}

function displayError(message) {
  const errorContainer = document.getElementById("error-container");
  errorContainer.innerHTML = `<p>${message}</p>`;
}

fetchData();
