First, make sure you have installed Express.js by running the command: `npm install express`

```javascript
// Import required modules
const express = require('express');

// Create an Express app
const app = express();

// Create a POST route '/sumOfEvenNumbers'
app.post('/sumOfEvenNumbers', (req, res) => {
  const numbers = req.body.numbers;

  // Calculate the sum of even numbers
  const sumOfEvenNumbers = numbers.reduce((acc, num) => {
    if (num % 2 === 0) {
      return acc + num;
    } else {
      return acc;
    }
  }, 0);

  // Send the sum of even numbers as response
  res.json({ sum: sumOfEvenNumbers });
});

// Start the server
app.listen(3000, () => {
  console.log('Server started on port 3000');
});
