Here is an example implementation of a CRUD API using Node.js and MongoDB, satisfying the given requirements:

1. Create a new document:

- Endpoint: POST /documents
- Request body: { "data": "example data" }
- Response: { "id": "document_id", "data": "example data" }

```javascript
app.post('/documents', authenticateUser, (req, res) => {
  const documentData = req.body.data;
  const userId = req.user.id;

  // Validation checks for documentData

  const newDocument = new Document({ data: documentData, userId });

  newDocument.save((err, savedDocument) => {
    if (err) {
      // Handle database error
      return res.status(500).json({ error: 'An error occurred while saving the document' });
    }
    res.status(201).json(savedDocument);
  });
});
```

2. Read a document:

- Endpoint: GET /documents/:id
- Response: { "id": "document_id", "data": "example data" }

```javascript
app.get('/documents/:id', authenticateUser, (req, res) => {
  const documentId = req.params.id;
  const userId = req.user.id;

  Document.findOne({ _id: documentId, userId }, (err, document) => {
    if (err) {
      // Handle database error
      return res.status(500).json({ error: 'An error occurred while retrieving the document' });
    }
    if (!document) {
      return res.status(404).json({ error: 'Document not found' });
    }
    res.json(document);
  });
});
```

3. Update a document:

- Endpoint: PUT /documents/:id
- Request body: { "data": "updated data" }
- Response: { "id": "document_id", "data": "updated data" }

```javascript
app.put('/documents/:id', authenticateUser, (req, res) => {
  const documentId = req.params.id;
  const userId = req.user.id;
  const updatedData = req.body.data;

  Document.findOneAndUpdate({ _id: documentId, userId }, { data: updatedData }, { new: true }, (err, updatedDocument) => {
    if (err) {
      // Handle database error
      return res.status(500).json({ error: 'An error occurred while updating the document' });
    }
    if (!updatedDocument) {
      return res.status(404).json({ error: 'Document not found' });
    }
    res.json(updatedDocument);
  });
});
```

4. Delete a document:

- Endpoint: DELETE /documents/:id
- Response: { "id": "document_id", "data": "example data" }

```javascript
app.delete('/documents/:id', authenticateUser, (req, res) => {
  const documentId = req.params.id;
  const userId = req.user.id;

  Document.findOneAndDelete({ _id: documentId, userId }, (err, deletedDocument) => {
    if (err) {
      // Handle database error
      return res.status(500).json({ error: 'An error occurred while deleting the document' });
    }
    if (!deletedDocument) {
      return res.status(404).json({ error: 'Document not found' });
    }
    res.json(deletedDocument);
  });
});
```

