          return;
        }

        // Validate password criteria
        if (!isValidPassword(user.password)) {
          console.error('Invalid password');
          return;
        }

        // Generate email address based on username
        user.email = generateEmail(user.username);

        // Store user information in database
        $http.post('/api/registerUser', user)
          .then(function(response) {
            // Send confirmation email
            $http.post('/api/sendConfirmationEmail', { email: user.email })
              .then(function(response) {
                console.log('Registration successful');
              })
              .catch(function(error) {
                console.error('Failed to send confirmation email');
              });
          })
          .catch(function(error) {
            console.error('Failed to register user');
          });
      })
      .catch(function(error) {
        console.error('Failed to check username');
      });
  };

  function isValidPassword(password) {
    var passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*])[A-Za-z\d!@#$%^&*]{8,}$/;
    return passwordRegex.test(password);
  }

  function generateEmail(username) {
    return username + '@example.com';
  }
});
```

In this example, the `registerUser` function takes a `user` object as input and performs the registration process. It first validates the uniqueness of the username by making an HTTP GET request to the server-side API endpoint `/api/checkUsername/` followed by the username. If the username is already taken, an error message is logged.

Next, the function validates the password criteria using a regular expression. If the password does not meet the criteria, an error message is logged.

If the username and password pass the validation steps, the function generates an email address based on the username and assigns it to the `user` object. The user information is then sent to the server-side API endpoint `/api/registerUser` via an HTTP POST request to store it in the database. If the registration is successful, a confirmation email is sent to the user's generated email address by making an HTTP POST request to `/api/sendConfirmationEmail`.

Any errors that occur during the registration process are logged to the console using `console.error`.

