```

4. Define the callback function to handle the response:
```javascript
xhr.onreadystatechange = function() {
  if (xhr.readyState === XMLHttpRequest.DONE) {
    if (xhr.status === 200) {
      // Handle the successful response here
      var compressedData = xhr.responseText;

      // Decompress the response using pako library (https://github.com/nodeca/pako)
      var binaryString = atob(compressedData);
      var byteArray = new Uint8Array(binaryString.length);
      for (var i = 0; i < binaryString.length; i++) {
        byteArray[i] = binaryString.charCodeAt(i);
      }
      var decompressedData = pako.inflate(byteArray, { to: 'string' });

      // Process the decompressed data here
      console.log(decompressedData);
    } else {
      // Handle any error responses here
      console.error('Request failed. Status:', xhr.status);
    }
  }
};
```

5. Finally, send the request:
