const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');

const app = express();
const port = 3000;

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/userdb', { useNewUrlParser: true, useUnifiedTopology: true });
