```javascript
// Function to check if a key exists in localStorage
function isLocalStorageKeyExists(key) {
  return localStorage.getItem(key) !== null;
}

// Function to set an item in localStorage with expiry time
function setLocalStorageItem(key, value, expiryInMinutes) {
  const now = new Date();
  const expiry = new Date(now.getTime() + expiryInMinutes * 60000);
  localStorage.setItem(key, JSON.stringify({
    value: value,
    expiry: expiry.getTime()
  }));
}

// Function to get an item from localStorage if it exists and not expired
function getLocalStorageItem(key) {
  if (isLocalStorageKeyExists(key)) {
    const item = JSON.parse(localStorage.getItem(key));
    const now = new Date().getTime();
    if (now < item.expiry) {
      return item.value;
    } else {
      localStorage.removeItem(key);
    }
  }
  return null;
}

// Function to fetch images with caching
async function fetchImages() {
  const cacheKey = `images_${page}_${searchTerm}_${selectedCategory}`;
  const cachedImages = getLocalStorageItem(cacheKey);
  if (cachedImages) {
    images = [...images, ...cachedImages];
    page++;
    renderImages();
