    const response = await fetch(`${API_URL}?page=${page}&search=${searchTerm}&category=${selectedCategory}`);
    const data = await response.json();
    images = [...images, ...data.results];
    page++;
    setLocalStorageItem(cacheKey, data.results, 60);
    renderImages();
  }
}
