```javascript
// Fetch the countries data
fetch('https://restcountries.com/v3.1/all')
  .then(response => response.json())
  .then(countriesData => {
    // Fetch the continents data
    fetch('https://example.com/continents.json')
      .then(response => response.json())
      .then(continentsData => {
        // Fetch the world population
        fetch('https://example.com/worldpopulation')
          .then(response => response.json())
          .then(worldPopulationData => {
