const express = require('express');
const axios = require('axios');

const app = express();

// Cache object to store weather data
const cache = {};

// Endpoint to get weather data for a specific location
app.get('/weather', async (req, res) => {
  const location = req.query.location;

  // Check if weather data for the location is already cached and not expired
  if (cache[location] && cache[location].expiresAt > new Date()) {
    return res.json(cache[location].data);
  }

  try {
    // Make external API call to get weather data
    const response = await axios.get('https://api.weatherprovider.com', {
      params: {
        location: location
      }
    });

    // Extract relevant data from the API response
    const weatherData = {
      condition: response.data.condition,
      temperature: response.data.temperature,
      timestamp: new Date().toUTCString()
    };

    // Cache the weather data with a configurable expiration time
    cache[location] = {
      data: weatherData,
      expiresAt: new Date(new Date().getTime() + 5 * 60 * 1000) // 5 minutes expiration
    };

    return res.json(weatherData);
  } catch (error) {
    // Handle API error
    return res.status(500).json({ error: 'Failed to retrieve weather data' });
  }
});

// Start the server
