```javascript
angular.module('registrationApp', [])
  .controller('RegistrationController', function($http, $log) {
    var vm = this;

    vm.registerUser = function() {
      // Validate username
      $http.get('https://external-api/check-username/' + vm.username)
        .then(function(response) {
          if (response.data.available) {
            // Validate password
            if (validatePassword(vm.password)) {
              // Generate unique email
              var email = generateEmail(vm.username);

              // Store user information in database
              var user = {
                username: vm.username,
                email: email
              };
              $http.post('https://database-api/users', user)
                .then(function(response) {
                  // Send confirmation email
                  sendConfirmationEmail(email);
                })
                .catch(function(error) {
                  $log.error('Error storing user information:', error);
                });
            } else {
              $log.error('Password does not meet criteria');
            }
          } else {
            $log.error('Username already taken');
          }
        })
        .catch(function(error) {
          $log.error('Error checking username availability:', error);
        });
    };

    function validatePassword(password) {
      var regex = /^(?=.*[a-z].*[a-z])(?=.*[A-Z].*[A-Z])(?=.*\d.*\d)(?=.*[!@#$%^&*].*[!@#$%^&*])(?!.*(.).*\1)[a-zA-Z\d!@#$%^&*]{12,}$/;
      return regex.test(password);
    }

    function generateEmail(username) {
      var randomString = Math.random().toString(36).substr(2, 10);
      var domain = 'example.com';
      return username + '-' + randomString + '@' + domain;
    }

    function sendConfirmationEmail(email) {
      $http.post('https://email-api/send-confirmation', { email: email })
        .then(function(response) {
          $log.info('Confirmation email sent');
        })
        .catch(function(error) {
          $log.error('Error sending confirmation email:', error);
        });
    }
  });
```

