```javascript
const apiEndpoint = 'https://api.example.com/users';
const itemsPerPage = 10;
let currentPage = 1;
let usersData = [];

// Fetch data from the API
function fetchData() {
  fetch(apiEndpoint)
    .then(response => response.json())
    .then(data => {
      usersData = data;
      renderTable();
    })
    .catch(error => {
      document.getElementById('table-body').innerHTML = 'Error fetching data from the API.';
    });
}

// Render the table with data
function renderTable() {
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const tableBody = document.getElementById('table-body');

  // Clear the table body
  tableBody.innerHTML = '';

  // Loop through the data and create rows
  for (let i = startIndex; i < endIndex && i < usersData.length; i++) {
    const user = usersData[i];

    const row = document.createElement('tr');
    row.innerHTML = `
      <td>${user.name}</td>
      <td>${user.age}</td>
      <td>${user.gender}</td>
    `;

    tableBody.appendChild(row);
  }

  updatePagination();
}

// Update pagination buttons
function updatePagination() {
  const paginationContainer = document.querySelector('.pagination');
  paginationContainer.style.display = usersData.length > itemsPerPage ? 'flex' : 'none';

  const previousButton = document.querySelector('.pagination button:first-child');
  previousButton.disabled = currentPage === 1;

  const nextButton = document.querySelector('.pagination button:last-child');
  nextButton.disabled = currentPage === Math.ceil(usersData.length / itemsPerPage);
}

// Switch to previous page
function previousPage() {
  if (currentPage > 1) {
    currentPage--;
    renderTable();
  }
}

// Switch to next page
function nextPage() {
  if (currentPage < Math.ceil(usersData.length / itemsPerPage)) {
    currentPage++;
    renderTable();
  }
}

// Sort the table data based on the selected column
function sortTable(column) {
  usersData.sort((a, b) => {
    if (a[column] < b[column]) return -1;
    if (a[column] > b[column]) return 1;
    return 0;
  });

  renderTable();
}

// Filter the table data based on the entered keyword
function searchTable() {
  const keyword = document.getElementById('search-input').value.toLowerCase();
  const filteredData = usersData.filter(user => {
    return user.name.toLowerCase().includes(keyword) ||
           user.age.toString().includes(keyword) ||
           user.gender.toLowerCase().includes(keyword);
  });

  usersData = filteredData;
  currentPage = 1;
  renderTable();
}

// Add event listener for search input
document.getElementById('search-input').addEventListener('input', searchTable);

// Fetch data when the page loads
fetchData();
```

This example fetches data from the provided API endpoint, parses the JSON response, and populates the table with the extracted information. It also implements pagination, sorting, and search functionality. CSS styling is applied to make the table visually appealing.

